import{z as s,x as l,o as e,c as i,q as t,j as r,D as E,d as n,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"基准选择的争议","description":"","frontmatter":{"title":"基准选择的争议","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-benchmark-selection.md","filePath":"quant/ap-benchmark-selection.md","lastUpdated":1791413859000}'),p={name:"quant/ap-benchmark-selection.md"};function d(h,a,c,D,m,u){const A=l("Mermaid");return e(),i("div",null,[a[2]||(a[2]=t('<h1 id="基准选择的争议" tabindex="-1">基准选择的争议 <a class="header-anchor" href="#基准选择的争议" aria-label="Permalink to &quot;基准选择的争议&quot;">​</a></h1><div class="epigraph"><p>用一组可投资的资产类指数可以还原基金收益的大半，剩下那截才叫选择；争议从来不在拟合，而在风格由谁、在何时指定。</p><footer>—— Sharpe, Asset Allocation: Management Style and Performance Measurement, Journal of Portfolio Management, 1992</footer></div><p><a href="/quant/ap-riskadjusted-family">上一课</a>展开比率族谱：每个分子的「超额」都指向一个基准。缺口是<strong>基准从哪来</strong>。超额是一个差分，减数换了，超额就换号；基准因此不是统计上「拟合最好」的对象，而是事前写进契约的条款。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三类候选各有暗坑。<strong>指数基准</strong>：与组合的风格可以漂移——一只偏中小盘的增强产品对大盘指数报超额，超额里一大块是规模暴露，不是选股。<strong>同业基准</strong>：分位数排名受幸存者偏差污染，清盘的基金退出样本，留下来的分位系统性偏乐观；排名还循环作用于行为，见<a href="/quant/fund-flows-chasing">基金流与回报追逐</a>。<strong>因子模型基准</strong>：把基准变成事后可调的回归——Sharpe 的收益风格分析用一组风格指数拟合，解释力很高，但窗口一换风格就换；它本是事后诊断工具，拿去事后重选基准，就把记分牌交给了被评分的人。缺口是一组基准判据与一份变更程序。</p><p><span class="marginnote">为什么重要：基准一换，超额就换号，而超额背后挂着奖金、清盘线与营销材料。同一支产品去年相对沪深 300 是 +3%，相对中证 500 可能是 −5%——投资者买到的是哪个数，取决于契约里写的是哪一行，而不取决于哪一行好看。</span></p><h3 id="好基准的判据" tabindex="-1">好基准的判据 <a class="header-anchor" href="#好基准的判据" aria-label="Permalink to &quot;好基准的判据&quot;">​</a></h3><p>判据是实务共识：<strong>事前指定</strong>、可投资（或其成分可复制成持仓）、可观测、与投资授权一致、成分与权重规则明确。不可投资的基准——含空头成分、含不可交易的权重约束——产生的 alpha 无法兑现成钱，评价悬空。基准还可以被「拿捏」：管理人事后主张换基准，或把组合风格漂到契约之外，两条路都让超额失真；前者要靠变更程序挡住，后者要靠暴露对齐报告抓住。</p>',8)),(e(),r(o,null,{default:E(()=>[B(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%BB%99%E4%BA%A7%E5%93%81%E5%AE%9A%E5%9F%BA%E5%87%86%22%7D%20--%3E%20IDX%5B%22%E6%8C%87%E6%95%B0%E5%9F%BA%E5%87%86%22%5D%0A%20%20Q%20--%3E%20PEER%5B%22%E5%90%8C%E4%B8%9A%E5%9F%BA%E5%87%86%22%5D%0A%20%20Q%20--%3E%20FM%5B%22%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%E5%9F%BA%E5%87%86%22%5D%0A%20%20IDX%20--%3E%20P1%5B%22%E5%9D%91%3A%20%E9%A3%8E%E6%A0%BC%E6%BC%82%E7%A7%BB%E6%97%B6%E8%B6%85%E9%A2%9D%E6%B7%B7%E5%85%A5%E8%A7%84%E6%A8%A1%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20PEER%20--%3E%20P2%5B%22%E5%9D%91%3A%20%E5%B9%B8%E5%AD%98%E8%80%85%E5%81%8F%E5%B7%AE%E8%AE%A9%E5%88%86%E4%BD%8D%E5%81%8F%E4%B9%90%E8%A7%82%22%5D%0A%20%20FM%20--%3E%20P3%5B%22%E5%9D%91%3A%20%E4%BA%8B%E5%90%8E%E5%8F%AF%E8%B0%83%2C%20%E8%AE%B0%E5%88%86%E7%89%8C%E4%BA%A4%E7%BB%99%E8%A2%AB%E8%AF%84%E5%88%86%E8%80%85%22%5D%0A%20%20P1%20--%3E%20FIX%5B%22%E6%94%B6%E5%8F%A3%3A%20%E4%BA%8B%E5%89%8D%E5%A5%91%E7%BA%A6%20%2B%20%E4%B8%8D%E8%BF%BD%E6%BA%AF%E7%9A%84%E5%8F%98%E6%9B%B4%E7%A8%8B%E5%BA%8F%20%2B%20%E6%9A%B4%E9%9C%B2%E5%AF%B9%E9%BD%90%22%5D%0A%20%20P2%20--%3E%20FIX%0A%20%20P3%20--%3E%20FIX%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：收益风格分析像赛后录像——它能告诉你这支球队实际踢的是什么阵型、哪里走位失当；但你不能因为某场录像好看，就中场休息时把球门挪窄一点。诊断工具归诊断，记分牌归契约，两样不能混用。</span></p><p><span class="marginnote">同一产品相对沪深 300 与相对中证 500 的年化超额可以差出几个百分点：基准不是度量细节，是记分牌本身。跟踪误差的工程口径见<a href="/quant/benchmark-tracking-error">基准与跟踪误差</a>，贴合度另看<a href="/quant/active-share">主动份额</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把基准写成契约条款，字段化：基准对象（指数或规则）、再平衡频率、成分调整规则、生效日期、变更程序（须经持有人或投委会同意，且<strong>不追溯</strong>已考核区间）。同业基准要声明样本构建：含死亡基金、共同起点、分组规则。收益风格分析的位置要钉死：它用回归<strong>事后诊断</strong>组合的实际风格暴露，服务于「解释这个组合像什么」；基准契约窗口与诊断窗口分开，诊断结果可以触发暴露对齐的整改，不能触发换基准。验收用三问：基准从哪条条款来、谁批准过变更、超额按哪一版基准算。</p>',4)),(e(),r(o,null,{default:E(()=>[B(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%3A%20%E6%8C%87%E6%95%B0%2F%E5%90%8C%E4%B8%9A%2F%E5%9B%A0%E5%AD%90%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20CRIT%5B%22%E5%88%A4%E6%8D%AE%3A%20%E4%BA%8B%E5%89%8D%2F%E5%8F%AF%E6%8A%95%E8%B5%84%2F%E5%8F%AF%E8%A7%82%E6%B5%8B%2F%E4%B8%80%E8%87%B4%E6%8E%88%E6%9D%83%22%5D%0A%20%20CRIT%20--%3E%20PASS%5B%22%E9%80%9A%E8%BF%87%E5%88%A4%E6%8D%AE%E7%9A%84%E5%80%99%E9%80%89%22%5D%0A%20%20PASS%20--%3E%20CONTRACT%5B%22%E5%9F%BA%E5%87%86%E5%A5%91%E7%BA%A6%E6%9D%A1%E6%AC%BE%E4%B8%8E%E5%8F%98%E6%9B%B4%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20CONTRACT%20--%3E%20EXCESS%5B%22%E8%B6%85%E9%A2%9D%20%3D%20%E7%BB%84%E5%90%88%20-%20%E5%9F%BA%E5%87%86%22%5D%0A%20%20DRIFT%5B%22%E9%A3%8E%E6%A0%BC%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20ALIGN%5B%22%E6%9A%B4%E9%9C%B2%E5%AF%B9%E9%BD%90%E6%8A%A5%E5%91%8A%22%5D%0A%20%20ALIGN%20--%3E%20EXCESS%0A%20%20RBSA%5B%22%E6%94%B6%E7%9B%8A%E9%A3%8E%E6%A0%BC%E5%88%86%E6%9E%90%3A%20%E4%BA%8B%E5%90%8E%E8%AF%8A%E6%96%AD%22%5D%20--%3E%20ALIGN%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>基准为什么必须事前：差分的对称性——在被减数与减数之间，事后选基准等于在超额的分布里挑有利的一侧，这与<a href="/quant/backtest-overfitting">回测过拟合</a>共享同一机制：选择抬高读数。可比性也来自事前：不同管理人用不同基准，截面排名不可加总，委员会看到的「前十名」可以只是十个记分牌。同业基准的机制性偏差要拆开看：幸存者让分位随时间向上漂，于是用同业分位考核，会把行业平均的业绩衰减误读成个人技能下降——衰减是策略层的（<a href="/quant/strategy-lifecycle">策略生命周期</a>），分位是样本层的，两层混在一张排名表里，奖惩就发错了对象。</p><p><span class="marginnote">常见误区：初学者容易以为好基准就是「历史上和组合拟合得最像的指数」。拟合优度是可以挑出来的——候选足够多时，总有一个事后看特别贴。一旦允许这样挑，超额读数就被选择效应抬高，跟反复调参数的回测过拟合是同一个坑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计跟踪误差预算与指数编制工程（<a href="/quant/benchmark-tracking-error">基准与跟踪误差</a>），也不重讲因子归因的回归细节（<a href="/quant/factor-attribution">因子归因</a>）。基准钉死之后，绩效评估还剩时间维度上的最后一问：超额会不会重复——持续性怎么测、怎么被测量设计伪造，是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>超额是差分，减数换了号就换：基准是契约条款，不是拟合结果。</li><li>判据五条：事前指定、可投资、可观测、授权一致、规则明确；不可投资的基准给出不可兑现的 alpha。</li><li>收益风格分析是事后诊断风格的工具，不能反过来用于事后换基准。</li><li>同业排名有幸存者偏差与样本漂移；分位变化与技能变化要分开读。</li><li>出处：Sharpe, <em>Journal of Portfolio Management</em>, 1992；判据口径据 CFA Institute 绩效评估惯例整理。</li></ul>',7))])}const F=s(p,[["render",d]]);export{_ as __pageData,F as default};
